const STATE = require('STATE')
const statedb = STATE(__filename)
const { sdb, get } = statedb(fallback_module)

module.exports = add_new_contact

async function add_new_contact(opts = {}, { onClose, onSubmit } = {}) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject,
    data: ondata,
    icons: iconject,
  }

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })

  let dricons = []

  shadow.innerHTML = `
    <div class="add-contact-container">
      <div class="add-contact-header">
        <div class="header-left">
          <span class="plus-icon">+</span>
          <span class="header-title">Add Contact</span>
        </div>
        <div class="x-icon"></div>
      </div>
      <div class="header-divider"></div>

      <div class="form-body">
        <div class="field-group">
          <label class="field-label">Name / Alias:</label>
          <input class="field-input" id="input-name" type="text" placeholder="e.g. Alice" autocomplete="off" />
        </div>

        <div class="field-group">
          <label class="field-label">Address (BTC / Lightning):</label>
          <input class="field-input" id="input-address" type="text" placeholder="bcrt1q... or lnbc..." autocomplete="off" />
        </div>

        <div class="field-group">
          <label class="field-label">Note <span class="optional-tag">(Optional)</span>:</label>
          <input class="field-input" id="input-note" type="text" placeholder="Coffee shop wallet..." autocomplete="off" />
        </div>

        <button class="save-btn" id="save-contact-btn">Save Contact</button>
      </div>
    </div>
    <style></style>
  `

  const style = shadow.querySelector('style')

  const inputName    = shadow.querySelector('#input-name')
  const inputAddress = shadow.querySelector('#input-address')
  const inputNote    = shadow.querySelector('#input-note')
  const saveBtn      = shadow.querySelector('#save-contact-btn')
  const closeBtn     = shadow.querySelector('.x-icon')

  const subs = await sdb.watch(onbatch)

  // Close button
  if (closeBtn) {
    closeBtn.onclick = () => {
      if (onClose) onClose()
    }
  }

  // Save Contact button
  saveBtn.addEventListener('click', () => {
    const name    = (inputName.value    || '').trim()
    const address = (inputAddress.value || '').trim()
    const note    = (inputNote.value    || '').trim()

    if (!name || !address) {
      const existing = shadow.querySelector('.form-error')
      if (!existing) {
        const err = document.createElement('div')
        err.className = 'form-error'
        err.textContent = 'Please fill in Name and Address fields.'
        saveBtn.parentNode.insertBefore(err, saveBtn)
        setTimeout(() => err.remove(), 3000)
      }
      return
    }

    if (onSubmit) onSubmit({ name, address, note })

    // Clear form after submit
    inputName.value    = ''
    inputAddress.value = ''
    inputNote.value    = ''

    if (onClose) onClose()
  })

  return el

  function fail(data, type) {
    throw new Error('invalid message', { cause: { data, type } })
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(
        paths.map(path => drive.get(path).then(file => file.raw))
      )
      const func = on[type] || fail
      await func(data, type)
    }
  }

  function inject(data) {
    style.textContent = data[0]
  }

  function iconject(data) {
    dricons = data
    const x_icon = shadow.querySelector('.x-icon')
    if (x_icon) x_icon.innerHTML = dricons[1] || '&#x2715;'
  }

  async function ondata(data) {}
}

function fallback_module() {
  return {
    api
  }

  function api(opts) {
    if (!opts) opts = {}
    if (!opts.value) opts.value = {}

    return {
      drive: {
        'icons/': {
          'lightning.svg': { '$ref': 'lightning.svg' },
          'x.svg':         { '$ref': 'x.svg' },
        },
        'style/': {
          'add_new_contact.css': { '$ref': 'add_new_contact.css' }
        },
        'data/': {
          'opts.json': { raw: opts || {} }
        }
      }
    }
  }
}
